TOPIC_SOURCE={'Algorithms':'mit-algorithms','Programming':'python','Operating systems':'ostep','Databases':'postgres','Distributed systems':'raft'}
OPEN={'short_answer','homework','collaborative'}
CHOICE={'multiple_choice','true_false','dropdown','visual','drag_drop','audio','game_2d','game_3d','live'}
def q(id,format,topic,prompt,options,correct,explanation,source=None,difficulty='medium',**extra):
 source=source or TOPIC_SOURCE[topic]
 if source!='original-audio':assert sources[source]['status']=='acquired',source
 if format in OPEN:
  # Mirrors validateQuestion in backend/knowledge/core.cjs.
  c=extra['criteria'];assert options==[] and correct==c and len(c)==5 and all(3<=len(x)<=160 for x in c),id
  assert len(re.split(r'(?:^|\s)\d+\.\s+',extra['rubric'])[1:])==5,id
 if format in CHOICE:assert len(correct)==1 and correct[0] in options and len(set(options))==len(options),id
 if format=='multiple_select':assert set(correct)<set(options),id
 if format in('ordering','matching'):assert sorted(options)==sorted(correct),id
 if format=='ordering':assert options!=correct,id
 if format=='matching':assert len(extra['labels'])==len(correct),id
 if format=='categorization':assert len(correct)==len(options) and set(correct)<=set(extra['groups']),id
 questions.append(dict(id=id,format=format,topic=topic,prompt=prompt,options=options,correct=correct,explanation=explanation,sourceId=source,sourceURL=sources.get(source,{}).get('url',''),difficulty=difficulty,**extra))
def written(id,format,topic,prompt,criteria,facts,explanation,difficulty='hard',**extra):
 rubric='Award exactly one point for each of the following five independently expressed facts. Do not infer unstated facts: '+' '.join(f'{i}. {f}' for i,f in enumerate(facts,1))
 q(id,format,topic,prompt,[],criteria,explanation,difficulty=difficulty,criteria=criteria,rubric=rubric,**extra)
